"use strict";(self.webpackChunk=self.webpackChunk||[]).push([[65150],{82912:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>r,default:()=>m,frontMatter:()=>o,metadata:()=>l,toc:()=>u});var a=n(74848),i=n(28453);const s='<nav class="breadcrumb has-arrow-separator" aria-label="breadcrumbs"><ul><li><a href="/docs/api/namespaces/#95420D3AD49404C0"><span>namespace celerity</span></a></li><li><a href="/docs/api/namespaces/#36211E2D24C9AB8E"><span>namespace experimental</span></a></li><li class="is-active"><a aria-current="page5006726B35E7A3E7"><span>enum class lookahead</span></a></li></ul></nav>\n<main><h1>enum class lookahead</h1><h2>Description</h2><p><p>Controls how many command groups the runtime can queue up until starting execution of the first one.</p>\n</p><p>Declared at: <a class="is-family-code" href="https://github.com/celerity/celerity-runtime/blob/v0.7.0/include/types.h#L192">include/types.h:192</a></p><h2>Enumerators</h2><table class="table is-narrow is-hoverable"><tr><th>Name</th><th>Value</th><th>Comment</th></tr><tr><td class="is-family-code">none</td><td class="is-family-code">0</td><td>Command groups begin executing as soon as possible, minimizing latency. This is the right choice when asynchronous command groups must overlap with user code in the application thread. Depending on the application, this might trigger frequent and expensive buffer resizes which can limit the maximum buffer allocation (and thus problem size) per device.</td></tr><tr><td class="is-family-code">automatic</td><td class="is-family-code">1</td><td>Queue up a window of command groups at the runtime&apos;s discretion. This is the default, and will combine buffer allocations and eliminate resizes and out-of-memory conditions in most applications.</td></tr><tr><td class="is-family-code">infinite</td><td class="is-family-code">2</td><td>Always queue up all command groups until the next synchronization point, i.e. `queue::fence`, `queue::wait` or runtime shutdown. This maximizes throughput and avoids suboptimal buffer allocations at the expense of higher up-front scheduling latency.</td></tr></table></main>',o={hide_title:!0,pagination_next:null,pagination_prev:null,custom_edit_url:null,sidebar_class_name:"sidebar-hidden",title:"enum class lookahead"},r=void 0,l={id:"api/enums/5006726B35E7A3E7",title:"enum class lookahead",description:"",source:"@site/celerity-runtime/docs/api/enums/5006726B35E7A3E7.mdx",sourceDirName:"api/enums",slug:"/api/enums/5006726B35E7A3E7",permalink:"/docs/api/enums/5006726B35E7A3E7",draft:!1,unlisted:!1,editUrl:null,tags:[],version:"current",frontMatter:{hide_title:!0,pagination_next:null,pagination_prev:null,custom_edit_url:null,sidebar_class_name:"sidebar-hidden",title:"enum class lookahead"},sidebar:"api"},c={},u=[];function d(e){const{Head:t}={...(0,i.R)(),...e.components};return t||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Head",!0),(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t,{children:[(0,a.jsx)("script",{src:"/js/highlight.min.js"}),(0,a.jsx)("script",{src:"/js/api_docs.js",defer:!0})]}),"\n",(0,a.jsx)("div",{dangerouslySetInnerHTML:{__html:s}})]})}function m(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},28453:(e,t,n)=>{n.d(t,{R:()=>o,x:()=>r});var a=n(96540);const i={},s=a.createContext(i);function o(e){const t=a.useContext(s);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),a.createElement(s.Provider,{value:t},e.children)}}}]);